import{TenBase,fmt,svgEl}from'./ten-base.js';import{clamp,dist}from'../math.js';import{factors,gcd,lcm,quadratic,ap,section,grouped,dicePairs}from'../ten-math.js';
export default class TenGraph extends TenBase{
 constructor(host,ctx){super(host,ctx);if(this.id===1&&this.mode==='irrational')this.button('Next proof step →','प्रमाण का अगला चरण →',()=>this.step=(this.step+1)%5);if(this.id===7)this.points=[[-3,-1],this.mode==='distance'?[this.v,3]:[3,this.mode==='midpoint'?this.v:3]];
 if(this.id===13){this.freqs=[4,6,this.v,5,3];const table=document.createElement('div');table.className='frequencyEditor';table.innerHTML=`<table class="freqTable"><thead><tr><th>${this.say('Class interval','वर्ग अंतराल')}</th><th>${this.say('Frequency','बारंबारता')}</th></tr></thead><tbody>${this.freqs.map((f,i)=>`<tr><td>${10*i}–${10*(i+1)}</td><td><input type="number" min="${i===2?1:0}" max="20" step="1" value="${f}" data-freq="${i}" aria-label="Frequency ${i*10}–${(i+1)*10} | बारंबारता"></td></tr>`).join('')}</tbody></table>`;this.controls.append(table);for(let el of table.querySelectorAll('input'))this.listen(el,'input',()=>{this.freqs[+el.dataset.freq]=el.value===''?NaN:+el.value;if(+el.dataset.freq===2){this.v=this.freqs[2];let input=this.controls.querySelector('input[type=range]');input.value=this.v;input.previousElementSibling.textContent=fmt(this.v)}this.changed=true;this.draw();ctx.onChange?.()})}
 if(this.id===14&&this.mode==='coin'){this.counts=[0,0];this.total=0;this.pending=0;this.button('Throw N times','N बार उछालें',()=>{this.pending+=this.v;this.playing=true;ctx.onPlaying?.(true);this.animate()});this.button('Clear trials','प्रयोग मिटाएँ',()=>{this.counts=[0,0];this.total=0;this.pending=0;this.playing=false;cancelAnimationFrame(this.frame);this.frame=null;ctx.onPlaying?.(false)});this.listen(document,'visibilitychange',()=>{this.last=0;if(!document.hidden&&this.playing)this.animate()})}this.draw()}
 update(k){if(this.id===7&&this.points.length){if(this.mode==='distance')this.points[1][0]=this.v;if(this.mode==='midpoint')this.points[1][1]=this.v}if(this.id===13&&this.freqs){this.freqs[2]=this.v;this.controls.querySelector('[data-freq="2"]').value=this.v}}
 move(i,p){if(this.id!==7)return;this.points[i]=[clamp(p[0],-7,7),clamp(p[1],-4.5,4.5)];if(i===1&&this.mode!=='section'){this.v=this.points[1][this.mode==='distance'?0:1];let el=this.controls.querySelector('input[type=range]');el.value=this.v;el.previousElementSibling.textContent=fmt(this.v)}}
 draw(){this.clear(![1,5,13,14].includes(this.id));const v=this.v,m=this.mode,s=(en,hi)=>this.say(en,hi);
 if(this.id===1){this.clear(false);if(m==='prime'){let fs=factors(v);this.text([-7,4],`${v} = ${fs.join(' × ')}`);let x=-7,y=2;fs.forEach((p,i)=>{this.circle([x+i*1.15,y],.4,'shape');this.text([x+i*1.15-.12,y-.12],p);if(i)this.line([x+(i-1)*1.15+.4,y],[x+i*1.15-.4,y],'gold')});this.report([`${s('Integer','पूर्णांक')} = ${v}`,`${s('Prime factors','अभाज्य गुणनखंड')}: ${fs.join(' × ')}`],['Factor order can change; the prime factors with multiplicity do not.','क्रम बदल सकता है; पुनरावृत्ति सहित अभाज्य गुणनखंड नहीं बदलते।'])}else if(m==='hcf'){let h=gcd(v,this.b),l=lcm(v,this.b);for(let j=0;j<2;j++){let n=j?this.b:v;this.line([-7,2-j*3],[7,2-j*3],'axis');for(let i=1;i<=Math.min(12,Math.floor(120/n));i++)this.mark([-7+i*n/9,2-j*3],i*n)}this.report([`a = ${v}; b = ${this.b}`,`HCF = ${h}; LCM = ${l}`,`${h} × ${l} = ${v} × ${this.b} = ${v*this.b}`],['Only the first few multiples are drawn; the identity is exact for positive integers.','केवल शुरुआती गुणज दिखते हैं; धनात्मक पूर्णांकों के लिए सर्वसमिका सटीक है।'])}else{let p=[2,3,5][v-1],steps=[s(`Assume √${p} = a/b in lowest terms.`,`मानें √${p} = a/b सरलतम रूप में है।`),`a² = ${p}b²`,s(`Prime ${p} divides a², so it divides a.`,`अभाज्य ${p}, a² को विभाजित करता है, इसलिए a को भी।`),s(`Write a = ${p}k; then b² = ${p}k², so ${p} divides b too.`,`a = ${p}k रखने पर b² = ${p}k²; अतः ${p}, b को भी विभाजित करता है।`),s('Contradiction: a and b have a common prime factor.','विरोधाभास: a और b में साझा अभाज्य गुणनखंड है।')];steps.slice(0,this.step+1).forEach((x,i)=>this.text([-7.5,4-i*1.5],`${i+1}. ${[`√${p} = a/b`,`a² = ${p}b²`,`${p} | a² ⇒ ${p} | a`,`a = ${p}k ⇒ ${p} | b`,s('Contradiction: a and b are not coprime','विरोधाभास: a और b सहअभाज्य नहीं हैं')][i]}`,{'font-size':13}));this.report([`${s('Proof step','प्रमाण का चरण')} ${this.step+1} / 5`,steps[this.step]],['This logical argument proves irrationality; rounded screen decimals do not.','तार्किक तर्क अपरिमेयता सिद्ध करता है; स्क्रीन के सन्निकट दशमलव नहीं।'])}return}
 if(this.id===2||this.id===4){let a=1,b=0,c=v;if(this.id===2){if(m==='coefficients'){b=-(v+this.b);c=v*this.b}else if(m==='degree'){a=v;b=2;c=-2}}else{if(m==='discriminant')b=-4;else if(m==='factor'){b=-(v+this.b);c=v*this.b}else{this.clear(false);let w=v,h=v+2;this.path([[-w/2,-h/2],[w/2,-h/2],[w/2,h/2],[-w/2,h/2]],'shape',true);this.text([-w/2,-h/2-.4],`x = ${v} cm`);this.text([w/2+.2,0],`x + 2 = ${h} cm`);this.report([`A = x(x + 2) = x² + 2x = ${fmt(w*h)} cm²`,`x² + 2x − ${fmt(w*h)} = 0`,s('The positive length is physically admissible.','धनात्मक लंबाई ही भौतिक रूप से स्वीकार्य है।')]);return}}
 let q=quadratic(a,b,c);this.curve(x=>a*x*x+b*x+c);q.roots.forEach(x=>this.mark([x,0],fmt(x)));this.report([`p(x) = ${fmt(a)}x² + (${fmt(b)})x + (${fmt(c)})`,`${s('Real zeroes','वास्तविक शून्यक')}: ${q.roots.length?q.roots.map(fmt).join(', '):s('None','कोई नहीं')}`,a?(q.roots.length?`D = ${fmt(q.D)}; α + β = ${fmt(-b/a)}; αβ = ${fmt(c/a)}`:`D = ${fmt(q.D)}; `+s('No real zeroes exist.','वास्तविक शून्यक नहीं हैं।')):s('a = 0: this is linear, not quadratic.','a = 0: यह रैखिक है, द्विघात नहीं।')],['Gold points mark x-axis intersections; a repeated zero is one touching point.','सुनहरे बिंदु X-अक्ष के प्रतिच्छेद हैं; दोहरा शून्यक 1 स्पर्श बिंदु देता है।']);return}
 if(this.id===3){if(m==='parallel'){this.equation(1,1,-3);this.equation(2,2,-v,'gold');this.report([`x + y = 3; 2x + 2y = ${v}`,v===6?s('Coincident: infinitely many solutions.','संपाती: अनंत हल।'):s('Parallel: no common solution.','समांतर: कोई उभयनिष्ठ हल नहीं।')]);return}let sum=v,diff=m==='eliminate'?2:1,x=(sum+diff)/2,y=(sum-diff)/2;this.equation(1,1,-sum);this.equation(1,-1,-diff,'gold');this.mark([x,y],`(${fmt(x)}, ${fmt(y)})`);this.report([`x + y = ${sum}; x − y = ${diff}`,`2x = ${sum+diff} ⇒ x = ${fmt(x)}`,`y = ${sum} − ${fmt(x)} = ${fmt(y)}`],['The intersection satisfies both equations simultaneously.','प्रतिच्छेद दोनों समीकरणों को एक साथ संतुष्ट करता है।']);return}
 if(this.id===5){this.clear(false);let a=m==='savings'?10:3,d=m==='terms'?this.d:m==='savings'?5:2,n=v,q=ap(a,d,n),vals=Array.from({length:n},(_,i)=>a+i*d),max=Math.max(1,...vals.map(Math.abs));vals.forEach((x,i)=>{let px=45+i*490/n,zero=220,ht=x/max*150;this.svg.append(svgEl('rect',{x:px,y:ht>=0?zero-ht:zero,width:Math.max(10,400/n),height:Math.abs(ht),fill:i===n-1?'#f0c775':'#78d5bc'}));this.svg.append(svgEl('text',{x:px,y:ht>=0?zero-ht-8:zero+Math.abs(ht)+18},fmt(x)))});this.report([`a = ${a}; d = ${d}; n = ${n}`,`a_n = ${a} + (${n} − 1) × (${d}) = ${q.last}`,`S_n = ${n}/2 × (${a} + ${q.last}) = ${q.sum}${m==='savings'?' ₹':''}`,m==='sum'?`a_1 + a_n = a_2 + a_(n−1) = ${a+q.last}`:''],['Terms occur at integer indices; a zero or negative difference is allowed.','पदों के क्रमांक पूर्णांक हैं; सार्व अंतर 0 या ऋणात्मक भी हो सकता है।']);return}
 if(this.id===7){let[a,b]=this.points,mid=section(a,b,m==='section'?v:1);this.line(a,b);this.point(a,0,'A');this.point(b,1,'B');this.mark(mid,m==='section'?'P':'M');let length=dist(a,b);this.report([`A(${fmt(a[0])}, ${fmt(a[1])}); B(${fmt(b[0])}, ${fmt(b[1])})`,`AB = √[(${fmt(b[0]-a[0])})² + (${fmt(b[1]-a[1])})²] = ${fmt(length)}`,`${m==='section'?`AP : PB = ${v} : 1`:'AM : MB = 1 : 1'}`,`P = (${fmt(mid[0])}, ${fmt(mid[1])})`],['Internal division uses positive weights; the point lies on the segment.','अंतःविभाजन में धनात्मक भार होते हैं; बिंदु रेखाखंड पर रहता है।']);return}
 if(this.id===13){this.drawStats();return}if(this.id===14)this.drawProbability();}
 drawStats(){this.clear(false);if(this.freqs.some((f,i)=>!Number.isInteger(f)||f<(i===2?1:0)||f>20)){this.report([this.say('Enter whole frequencies 0–20; class 20–30 must have 1–20.','0–20 पूर्णांक बारंबारताएँ भरें; वर्ग 20–30 में 1–20 रखें।')]);return}let q=grouped(this.freqs),max=Math.max(...this.freqs),selected=this.mode==='median'?[q.medianIndex]:this.mode==='mode'?q.modalIndices:[];this.svg.append(svgEl('path',{d:'M65 50V320H555',class:'axis',fill:'none'}));this.freqs.forEach((f,i)=>{this.svg.append(svgEl('rect',{x:65+i*96,y:320-f/max*240,width:96,height:f/max*240,fill:selected.includes(i)?'#f0c775':'#78d5bc',stroke:'#163f35'}));this.svg.append(svgEl('text',{x:75+i*96,y:345},`${i*10}–${i*10+10}`));this.svg.append(svgEl('text',{x:105+i*96,y:310-f/max*240},f))});this.svg.append(svgEl('text',{x:65,y:25},this.say('Frequency','बारंबारता')));this.svg.append(svgEl('text',{x:130,y:385},this.say('Class interval (equal width 10)','वर्ग अंतराल (समान चौड़ाई 10)')));this.report([`N = ${q.n}; Σf_i x_i = ${q.sum}`,`x̄ ≈ ${fmt(q.mean)}; Median ≈ ${fmt(q.median)}`,q.mode===null?this.say('Tied modal classes: no unique modal-class estimate.','बहुलक वर्ग बराबर हैं: अद्वितीय बहुलक-वर्ग अनुमान नहीं।'):`Mode ≈ ${fmt(q.mode)}`,`Median: l=${q.medianIndex*10}, cf=${q.cf}, f=${this.freqs[q.medianIndex]}, h=10`],['Class-mark mean and interpolated median/mode are grouped-data estimates, not exact raw observations.','वर्ग-चिह्न माध्य और अंतर्वेशित माध्यिका/बहुलक वर्गीकृत आँकड़ों के अनुमान हैं, मूल प्रेक्षणों के सटीक मान नहीं।'])}
 drawProbability(){this.clear(false);if(this.mode==='coin'){let total=this.total||0,counts=this.counts||[0,0];for(let i=0;i<2;i++){let freq=total?counts[i]/total:0;this.svg.append(svgEl('rect',{x:150+i*180,y:320-freq*240,width:100,height:freq*240,fill:'#78d5bc'}));this.svg.append(svgEl('text',{x:160+i*180,y:350},i?'T / पट':'H / चित'));this.svg.append(svgEl('text',{x:160+i*180,y:310-freq*240},`${counts[i]} / ${total}`))}this.svg.append(svgEl('line',{x1:85,y1:200,x2:520,y2:200,stroke:'#f0c775','stroke-dasharray':'7 5'}));this.svg.append(svgEl('text',{x:80,y:35},this.say('Relative frequency; dotted line = 0.5','सापेक्ष बारंबारता; बिंदीदार रेखा = 0.5')));this.report([`N = ${total}; ${this.say('Pending','शेष')} = ${this.pending||0}`,`P(H) = P(T) = 1/2`,total?`f(H)/N = ${fmt(counts[0]/total)}`:this.say('No trials: empirical ratio is undefined.','प्रयोग नहीं: प्रायोगिक अनुपात अपरिभाषित है।')],['Finite random trials need not equal theoretical probability.','सीमित यादृच्छिक प्रयोगों का अनुपात सैद्धान्तिक प्रायिकता के बराबर होना अनिवार्य नहीं।']);return}if(this.mode==='dice'){for(let i=1;i<=6;i++)for(let j=1;j<=6;j++){let x=100+(i-1)*65,y=38+(j-1)*49;this.svg.append(svgEl('rect',{x,y,width:62,height:46,fill:i+j===this.v?'#f0c775':'#8bbca9',stroke:'#163f35'}));this.svg.append(svgEl('text',{x:x+9,y:y+28,class:'tileText'},`${i},${j}`))}let pairs=dicePairs(this.v);this.report([`${this.say('Target sum','वांछित योग')} = ${this.v}`,`${this.say('Favourable ordered pairs','अनुकूल क्रमित युग्म')} = ${pairs.length}`,`P(E) = ${pairs.length}/36 = ${fmt(pairs.length/36)}`],['The 36 ordered pairs are equally likely; the 11 possible sums are not.','36 क्रमित युग्म समान संभावित हैं; 11 संभावित योग समान संभावित नहीं हैं।']);return}for(let i=1;i<=6;i++){this.circle([-6+i*1.7,1],.5,i<=this.v?'gold':'shape');this.text([-6.12+i*1.7,.85],i,{class:i<=this.v?'tileText':''})}this.report([`E: result ≤ ${this.v}`,`P(E) = ${this.v}/6; P(not E) = ${6-this.v}/6`,`P(E) + P(not E) = 1`]);}
 animate(){if(this.frame||!this.playing)return;const run=time=>{this.frame=null;if(!this.playing||document.hidden)return;let dt=this.last?Math.max(0,Math.min(.1,(time-this.last)/1000)):0;this.last=time;this.acc=(this.acc||0)+dt*180*this.speed;let n=Math.min(this.pending,Math.floor(this.acc));this.acc-=n;for(let i=0;i<n;i++){this.counts[Math.random()<.5?0:1]++;this.total++;this.pending--}if(n&&(!this.ctx.lowpower||!this.lastDraw||time-this.lastDraw>=32||!this.pending)){this.draw();this.lastDraw=time;this.ctx.onChange?.()}if(this.pending>0)this.frame=requestAnimationFrame(run);else{this.playing=false;this.ctx.onPlaying?.(false)}};this.frame=requestAnimationFrame(run)}
 pause(){if(this.id!==14||this.mode!=='coin')return false;this.playing=!this.playing;this.last=0;if(this.playing){if(!this.pending)this.pending=this.v;this.animate()}else{cancelAnimationFrame(this.frame);this.frame=null}return this.playing}
}
